def read_number(prompt):
    while True:
        try:
            text = input(prompt)
        except EOFError:
            return None
        if text.strip().lower() == "cancel":
            return None
        try:
            return float(text)
        except ValueError:
            print("Please enter a number or cancel")

value = read_number("Measurement or cancel: ")
if value is None:
    print("Cancelled")
else:
    print("Measurement:", value)
